import React from 'react';
import { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Row, Col, Label } from 'reactstrap';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import { CommonLoader } from 'views/admin/Common/Loader';
import { showToast } from 'actions/admin/auth';
import { fetchBatchCoursesPlainApi, fetchEmployeeCoursesService } from 'actions/admin/courses';
import { fetchCourseStudentsListApi } from 'actions/admin/students';
import { fetchSchoolEmployeesApi } from 'actions/admin/employees';
import { fetchTimelineFeedApi, createTimelinePostApi, deleteTimelinePostApi } from 'actions/admin/timeline';
import { getGlobalSchoolUtils, getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import constants, { courseStatic, coursesStatic } from 'config/constants';
import { timelineUserFor, timelineErrorMessage } from './timelineUtils';
import TimelineComposer from './components/TimelineComposer';
import TimelinePostCard from './components/TimelinePostCard';
import { markManyViewedService } from 'actions/admin/contentView';
import TimelineEmptyState from './components/TimelineEmptyState';

const PAGE_SIZE = 10;

// Timeline: class-wise posts (text, photos, videos) that the class's guardians see in the mobile app.
// Teachers post and comment, and only in the classes they are assigned to; they can delete only their own posts. Admins
// can open any class but only view: no posting and no commenting. The backend does not check any of this (it lets any
// teacher or admin of the school do both in any class), so these rules are applied here. Admins start on the first class.
// Layout: one column of post cards; a post's comments open on the right of its own card (View comments / Close).
const TimelinePage = () => {
  const dispatch = useDispatch();
  const token = useSelector(state => state.auth.loggedUserToken);
  const role = useSelector(state => state.auth.loggedUserRole);
  const loggedUserId = useSelector(state => state.auth.loggedUserId);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const { batchId } = getGlobalCurrentBatchUtils();
  const user = useMemo(() => timelineUserFor(role, loggedUserId), [role, loggedUserId]);
  const isTeacher = role === constants.roles.teacher;

  const [courses, setCourses] = useState([]);
  const [coursesLoading, setCoursesLoading] = useState(true);
  const [courseId, setCourseId] = useState(null);
  const [posts, setPosts] = useState([]);
  const [pageInfo, setPageInfo] = useState({ number: 0, totalPages: 0 });
  const [feedLoading, setFeedLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [posting, setPosting] = useState(false);
  const [employeesById, setEmployeesById] = useState({});
  const [students, setStudents] = useState([]);
  const [deletePost, setDeletePost] = useState(null);
  const [deleting, setDeleting] = useState(false);
  const feedRequest = useRef(0);

  const showWarning = (message, type) => dispatch(showToast(message, type));
  const course = courses.find(c => c.courseId === courseId);

  // The classes of the academic year, and the one to start on.
  useEffect(() => {
    if (!batchId || !user) {
      setCoursesLoading(false);
      return;
    }
    // A teacher gets only the classes they are assigned to; an admin gets every class of the year.
    (isTeacher
      ? dispatch(fetchEmployeeCoursesService({ employeeId: loggedUserId, batchId, token })).then(list => list || [])
      : fetchBatchCoursesPlainApi({ batchId, token }).then(res => res.data || [])
    )
      .then(list => {
        setCourses(list);
        if (list[0]) setCourseId(list[0].courseId);
      })
      .catch(err => showWarning(timelineErrorMessage(err), 'error'))
      .finally(() => setCoursesLoading(false));
  }, [batchId, loggedUserId, role]);

  // Names for the author line (posts only carry the teacher's id).
  useEffect(() => {
    if (!schoolId) return;
    fetchSchoolEmployeesApi({ schoolId, token }).then(list =>
      setEmployeesById((list || []).reduce((acc, e) => ({ ...acc, [e.employeeId]: e }), {}))
    );
  }, [schoolId]);

  const loadFeed = useCallback(
    async (page, append) => {
      if (!courseId || !user) return;
      const requestId = ++feedRequest.current;
      append ? setLoadingMore(true) : setFeedLoading(true);
      try {
        const res = await fetchTimelineFeedApi({ courseId, user, page, size: PAGE_SIZE, token });
        if (requestId !== feedRequest.current) return;
        const content = res.data.content || [];
        setPosts(prev => (append ? [...prev, ...content] : content));
        // a teacher reading the feed has seen these posts (the backend records guardians and teachers, not admins)
        if (isTeacher && content.length) {
          markManyViewedService({
            token,
            contentType: 'TIMELINE_POST',
            contentIds: content.map(post => post.postId),
          }).catch(() => {});
        }
        setPageInfo({ number: res.data.page?.number ?? page, totalPages: res.data.page?.totalPages ?? 0 });
      } catch (err) {
        if (requestId !== feedRequest.current) return;
        showWarning(timelineErrorMessage(err), 'error');
      }
      if (requestId === feedRequest.current) {
        setFeedLoading(false);
        setLoadingMore(false);
      }
    },
    [courseId, user, token]
  );

  useEffect(() => {
    setPosts([]);
    setPageInfo({ number: 0, totalPages: 0 });
    setStudents([]);
    if (!courseId) return;
    loadFeed(0, false);
    // The class's students: names for the comment authors (a comment is stored against a student).
    fetchCourseStudentsListApi({ courseId, batchId, token })
      .then(res => setStudents(res.data || []))
      .catch(() => {});
  }, [courseId]);

  const handlePost = async ({ content, files }) => {
    setPosting(true);
    try {
      await createTimelinePostApi({ courseId, user, content, files, token });
      showWarning('Posted to the timeline', 'success');
      setPosting(false);
      loadFeed(0, false);
      return true;
    } catch (err) {
      showWarning(timelineErrorMessage(err), 'error');
      setPosting(false);
      return false;
    }
  };

  const confirmDelete = async () => {
    setDeleting(true);
    try {
      await deleteTimelinePostApi({ postId: deletePost.postId, user, token });
      showWarning('Post deleted', 'success');
      setPosts(prev => prev.filter(p => p.postId !== deletePost.postId));
    } catch (err) {
      showWarning(timelineErrorMessage(err), 'error');
    }
    setDeleting(false);
    setDeletePost(null);
  };

  if (!schoolId || !batchId) {
    return (
      <div className="content">
        <div style={{ textAlign: 'center', color: '#9a9a9a', padding: 40 }}>
          Please select a school and an academic year first.
        </div>
      </div>
    );
  }
  if (coursesLoading) return <CommonLoader />;

  const courseOptions = courses.map(c => ({ value: c.courseId, label: `${c.name} (${c.code})` }));
  // Same rule as the backend: only the teacher who wrote a post can delete it.
  const canDelete = post => user?.userType === 'EMPLOYEE' && post.employeeId === user.userId;
  // Posts carry only the author's id (no name), so look the teacher up; an id with no match is "School staff".
  const authorLabel = post => (canDelete(post) ? 'You' : employeesById[post.employeeId]?.name || 'School staff');

  return (
    <div className="content">
      {!courses.length ? (
        // Nothing to open: for a teacher, no class has been given to them yet (the school admin does that under School).
        <div className="mt-3">
          {isTeacher ? (
            <TimelineEmptyState
              icon="fas fa-chalkboard-teacher"
              title={`No ${courseStatic.toLowerCase()} assigned to you yet`}
              hint={`The Timeline shows the ${coursesStatic.toLowerCase()} you teach. Once your school admin assigns you a subject in a ${courseStatic.toLowerCase()}, it will appear here.`}
            />
          ) : (
            <TimelineEmptyState
              icon="fas fa-school"
              title={`No ${coursesStatic.toLowerCase()} in this academic year`}
              hint={`Add ${coursesStatic.toLowerCase()} under School to see what is shared with each one.`}
            />
          )}
        </div>
      ) : (
        <div>
          <Row>
            <Col md={6} sm={12}>
              <Label className="form-label">
                {courseStatic} <sup style={{ color: 'red' }}>*</sup>
              </Label>
              <CustomSelect
                noLabel
                name="courseId"
                value={courseId}
                options={courseOptions}
                placeholder={`Select ${courseStatic.toLowerCase()}`}
                onChange={(name, value) => setCourseId(value)}
              />
            </Col>
          </Row>
          <Row className="mt-3">
            <Col xs={12}>
              {isTeacher && (
                <TimelineComposer
                  authorName={employeesById[loggedUserId]?.name}
                  courseName={course?.name}
                  disabled={!courseId}
                  posting={posting}
                  onPost={handlePost}
                />
              )}
              {!courseId ? (
                <TimelineEmptyState
                  icon="fas fa-chalkboard"
                  title={`Select a ${courseStatic.toLowerCase()}`}
                  hint={`Pick a ${courseStatic.toLowerCase()} above to see what has been shared with it.`}
                />
              ) : feedLoading ? (
                <CommonLoader />
              ) : posts.length ? (
                <>
                  {posts.map(post => (
                    <TimelinePostCard
                      key={post.postId}
                      post={post}
                      authorLabel={authorLabel(post)}
                      courseName={course?.name}
                      canDelete={canDelete(post)}
                      canComment={isTeacher}
                      students={students}
                      user={user}
                      token={token}
                      showWarning={showWarning}
                      onDelete={setDeletePost}
                    />
                  ))}
                  {pageInfo.number + 1 < pageInfo.totalPages && (
                    <div style={{ textAlign: 'center', marginBottom: 20 }}>
                      <CustomButton
                        variant="outlined"
                        name="Load more"
                        loading={loadingMore}
                        disabled={loadingMore}
                        onClick={() => loadFeed(pageInfo.number + 1, true)}
                      />
                    </div>
                  )}
                </>
              ) : (
                <TimelineEmptyState
                  icon="far fa-images"
                  title={`No posts yet for ${course?.name}`}
                  hint={
                    isTeacher
                      ? 'Be the first to share an update, photo or video with this class using the box above.'
                      : 'Updates, photos and videos shared by teachers with this class will show up here.'
                  }
                />
              )}
            </Col>
          </Row>
        </div>
      )}
      <ConfirmModal
        confirmModalOpen={!!deletePost}
        confirmMessage="Delete this post and its photos/videos?"
        loading={deleting}
        deleteConfirm={confirmDelete}
        deleteCancel={() => setDeletePost(null)}
      />
    </div>
  );
};

export default TimelinePage;
