import React from 'react';
import { useState } from 'react';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { cardStyle } from '../timelineUtils';
import TimelineAvatar from './TimelineAvatar';
import TimelineMedia from './TimelineMedia';
import RichText from 'views/admin/Common/RichText';
import TimelineCommentsPanel from './TimelineCommentsPanel';
import { ViewsButton } from 'views/admin/Common/ContentViews';

// One post of the feed: author + time, text, photos/videos on the left. "View comments" opens that post's comments on
// the right of the same card (Close hides them again); until then the post uses the full width.
const TimelinePostCard = ({
  post,
  authorLabel,
  courseName,
  canDelete,
  canComment,
  students,
  user,
  token,
  showWarning,
  onDelete,
}) => {
  const [commentsOpen, setCommentsOpen] = useState(false);
  const posted = post.creationDateTime ? moment(post.creationDateTime) : null;

  const postColumn = (
    <div style={{ flex: '1 1 340px', minWidth: 0 }}>
      <div style={{ display: 'flex', alignItems: 'center' }}>
        <TimelineAvatar name={authorLabel} />
        <div style={{ marginLeft: 12, flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 'bold', color: colors.grey1 }}>{authorLabel}</div>
          <div style={{ fontSize: 12, color: '#9a9a9a' }} title={posted ? posted.format('DD MMM YYYY, hh:mm A') : ''}>
            {posted ? posted.fromNow() : ''}
            {courseName && (
              <span
                style={{
                  marginLeft: 8,
                  background: '#EDE1F7',
                  color: colors.accentDark,
                  borderRadius: 10,
                  padding: '1px 8px',
                  fontWeight: 'bold',
                }}>
                {courseName}
              </span>
            )}
          </div>
        </div>
        {canDelete && (
          <CustomButton
            size="small"
            variant="outlined"
            color="default"
            style={{ color: '#c62828', borderColor: '#c62828' }}
            name="Delete"
            onClick={() => onDelete(post)}
          />
        )}
      </div>
      {!!post.content && (
        <div
          style={{
            whiteSpace: 'pre-wrap',
            wordBreak: 'break-word',
            margin: '12px 0',
            fontSize: 15,
            lineHeight: 1.5,
            color: colors.grey1,
          }}>
          <RichText text={post.content} embed />
        </div>
      )}
      {!!post.media?.length && (
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: post.media.length > 1 ? 'repeat(auto-fit, minmax(200px, 1fr))' : '1fr',
            gap: 8,
            margin: '12px 0',
          }}>
          {post.media.map(media => (
            <TimelineMedia key={media.mediaId} media={media} user={user} token={token} />
          ))}
        </div>
      )}
      {!commentsOpen && (
        <div
          style={{
            borderTop: '1px solid #f1e9f7',
            paddingTop: 10,
            marginTop: 4,
            display: 'flex',
            alignItems: 'center',
            flexWrap: 'wrap',
            gap: 10,
          }}>
          <span
            role="button"
            tabIndex={0}
            onClick={() => setCommentsOpen(true)}
            onKeyDown={e => e.key === 'Enter' && setCommentsOpen(true)}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              cursor: 'pointer',
              fontSize: 13,
              fontWeight: 'bold',
              borderRadius: 16,
              padding: '4px 14px',
              color: colors.accent,
              background: '#F5EDFB',
            }}>
            <i className="far fa-comment" style={{ marginRight: 6 }} />
            View comments
          </span>
          <ViewsButton
            contentType="TIMELINE_POST"
            contentId={post.postId}
            style={{ padding: '4px 14px', borderRadius: 16, fontSize: 13 }}
          />
        </div>
      )}
    </div>
  );

  return (
    <div style={{ ...cardStyle, padding: 16, marginBottom: 16, display: 'flex', flexWrap: 'wrap', gap: 16 }}>
      {postColumn}
      {commentsOpen && (
        <div style={{ flex: '1 1 300px', minWidth: 0, borderLeft: '1px solid #f1e9f7', paddingLeft: 16 }}>
          <TimelineCommentsPanel
            post={post}
            students={students}
            user={user}
            token={token}
            canComment={canComment}
            showWarning={showWarning}
            onClose={() => setCommentsOpen(false)}
          />
        </div>
      )}
    </div>
  );
};

export default TimelinePostCard;
