import React from 'react';
import { useState, useEffect } from 'react';
import { fetchTimelineMediaBlobApi } from 'actions/admin/timeline';
import colors from 'config/colors';

const boxStyle = {
  width: '100%',
  height: 220,
  borderRadius: 6,
  background: '#f1f1f1',
  color: '#9a9a9a',
  fontSize: 12,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
};

// One photo or video of a post. Images load straight away; a video loads only once Play is pressed
// (they can be large, and a feed may carry many).
const TimelineMedia = ({ media, user, token }) => {
  const isVideo = media.mediaType === 'VIDEO';
  const [src, setSrc] = useState(null);
  const [failed, setFailed] = useState(false);
  const [wantsLoad, setWantsLoad] = useState(!isVideo);

  useEffect(() => {
    if (!wantsLoad) return undefined;
    let objectUrl = null;
    let cancelled = false;
    fetchTimelineMediaBlobApi({ mediaId: media.mediaId, user, token })
      .then(res => {
        if (cancelled) return;
        objectUrl = URL.createObjectURL(res.data);
        setSrc(objectUrl);
      })
      .catch(() => !cancelled && setFailed(true));
    return () => {
      cancelled = true;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [wantsLoad, media.mediaId]);

  if (failed) return <div style={boxStyle}>Could not load {media.fileName}</div>;
  if (!wantsLoad) {
    return (
      <div
        role="button"
        tabIndex={0}
        onClick={() => setWantsLoad(true)}
        onKeyDown={e => e.key === 'Enter' && setWantsLoad(true)}
        style={{ ...boxStyle, cursor: 'pointer', color: colors.accent, flexDirection: 'column' }}>
        <i className="fas fa-play-circle" style={{ fontSize: 34 }} />
        <span style={{ marginTop: 6 }}>Play video &middot; {media.fileName}</span>
      </div>
    );
  }
  if (!src) return <div style={boxStyle}>Loading...</div>;
  return isVideo ? (
    <video src={src} controls autoPlay style={{ width: '100%', maxHeight: 360, borderRadius: 6, background: '#000' }} />
  ) : (
    <img
      src={src}
      alt={media.fileName}
      style={{ width: '100%', maxHeight: 360, objectFit: 'contain', borderRadius: 6, background: '#f7f7f7' }}
    />
  );
};

export default TimelineMedia;
