import React from 'react';
import { useState, useEffect, useMemo } from 'react';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import { CommonLoader } from 'views/admin/Common/Loader';
import { fetchTimelineCommentsApi, addTimelineCommentApi } from 'actions/admin/timeline';
import { formStudentName } from 'config/constants';
import { toTitleCase } from 'utils/commonFunc';
import { timelineErrorMessage } from '../timelineUtils';
import colors from 'config/colors';
import { LinkifiedText } from 'views/admin/Common/RichText';
import TimelineAvatar from './TimelineAvatar';

// The backend marks who wrote a comment: profession is STUDENT (the guardian, commenting as their child), TEACHER or
// ADMIN, and name is that person's name.
const STAFF_LABEL = { ADMIN: 'Admin', TEACHER: 'Teacher' };
const isStaffComment = comment => !!STAFF_LABEL[comment.profession];

// The right-hand side of a post's card, shown after "View comments" is pressed: that post's comments in their own
// scrolling list, with a Close button.
// A comment is stored against a student (the guardian app comments as the student), so it is shown as
// the guardian's, together with every one of their children in this class ("Parent of A & B").
// Admins and teachers can comment too; their comments get a highlighted look with their name and role.
const TimelineCommentsPanel = ({ post, students, user, token, canComment, showWarning, onClose }) => {
  const [comments, setComments] = useState([]);
  const [loading, setLoading] = useState(false);
  const [draft, setDraft] = useState('');
  const [sending, setSending] = useState(false);

  const studentsById = useMemo(() => students.reduce((acc, s) => ({ ...acc, [s.studentId]: s }), {}), [students]);

  const load = postId => {
    setLoading(true);
    return fetchTimelineCommentsApi({ postId, user, token })
      .then(res => setComments(res.data || []))
      .catch(err => {
        setComments([]);
        showWarning(timelineErrorMessage(err), 'error');
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    setDraft('');
    setComments([]);
    load(post.postId);
  }, [post?.postId]);

  const send = async () => {
    setSending(true);
    try {
      await addTimelineCommentApi({ postId: post.postId, user, commentText: draft.trim(), token });
      setDraft('');
      await load(post.postId);
    } catch (err) {
      showWarning(timelineErrorMessage(err), 'error');
    }
    setSending(false);
  };

  const describe = comment => {
    if (isStaffComment(comment)) {
      return {
        name: comment.name || STAFF_LABEL[comment.profession],
        staff: true,
        sub: STAFF_LABEL[comment.profession],
      };
    }
    const student = studentsById[comment.studentId];
    if (!student) return { name: comment.name || `Student #${comment.studentId}`, sub: '' };
    const children = students
      .filter(s => s.guardianId === student.guardianId)
      .map(s => toTitleCase(formStudentName(s)));
    return {
      name: toTitleCase(student.guardName || formStudentName(student)),
      sub: `Parent of ${children.join(' & ')}`,
    };
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
      <div
        style={{
          padding: '0 0 10px',
          borderBottom: '1px solid #f1e9f7',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}>
        <div style={{ fontWeight: 'bold', color: colors.accentDark }}>
          Comments{!loading ? ` (${comments.length})` : ''}
        </div>
        <button
          type="button"
          aria-label="Close comments"
          title="Close"
          onClick={onClose}
          style={{
            border: 'none',
            background: 'transparent',
            fontSize: 24,
            lineHeight: 1,
            padding: '0 6px',
            color: colors.grey3,
            cursor: 'pointer',
          }}>
          &times;
        </button>
      </div>
      <div style={{ flex: 1, minHeight: 0, maxHeight: 420, overflowY: 'auto', padding: '12px 4px 4px 0' }}>
        {loading ? (
          <CommonLoader />
        ) : comments.length ? (
          comments.map(comment => {
            const { name, sub, staff } = describe(comment);
            return (
              <div
                key={comment.commentId}
                style={{
                  display: 'flex',
                  marginBottom: 12,
                  padding: 10,
                  borderRadius: 10,
                  background: staff ? '#F5EDFB' : '#fafafa',
                  borderLeft: `4px solid ${staff ? colors.accent : 'transparent'}`,
                }}>
                <TimelineAvatar name={name} size={34} admin={staff} />
                <div style={{ marginLeft: 10, minWidth: 0, flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap' }}>
                    <b style={{ fontSize: 13 }}>{name}</b>
                    {staff && (
                      <span
                        style={{
                          marginLeft: 6,
                          fontSize: 10,
                          fontWeight: 'bold',
                          letterSpacing: 0.5,
                          color: colors.white,
                          background: colors.accent,
                          borderRadius: 8,
                          padding: '1px 7px',
                        }}>
                        {sub.toUpperCase()}
                      </span>
                    )}
                    <span style={{ marginLeft: 'auto', fontSize: 11, color: '#9a9a9a' }}>
                      {comment.creationDateTime ? moment(comment.creationDateTime).fromNow() : ''}
                    </span>
                  </div>
                  {!staff && !!sub && <div style={{ fontSize: 11, color: '#7d7d7d' }}>{sub}</div>}
                  <div style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word', fontSize: 13, marginTop: 4 }}>
                    <LinkifiedText text={comment.commentText} />
                  </div>
                </div>
              </div>
            );
          })
        ) : (
          <div style={{ textAlign: 'center', padding: '28px 8px', color: colors.grey3 }}>
            <i className="far fa-comments" style={{ fontSize: 30, color: colors.accent, opacity: 0.6 }} />
            <div style={{ fontWeight: 'bold', fontSize: 14, color: colors.accentDark, marginTop: 8 }}>
              No comments yet
            </div>
            <div style={{ fontSize: 12, marginTop: 2 }}>Comments from guardians and teachers will appear here.</div>
          </div>
        )}
      </div>
      {canComment && (
        <div style={{ paddingTop: 10, borderTop: '1px solid #f1e9f7', display: 'flex', gap: 8 }}>
          <input
            className="form-control"
            style={{ padding: '6px 12px' }}
            maxLength={1000}
            placeholder="Write a comment..."
            value={draft}
            onChange={e => setDraft(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && draft.trim() && !sending && send()}
          />
          <CustomButton name="Send" disabled={!draft.trim() || sending} loading={sending} onClick={send} />
        </div>
      )}
    </div>
  );
};

export default TimelineCommentsPanel;
