import React from 'react';
import { useState, useEffect, useRef, useMemo } from 'react';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { courseStatic } from 'config/constants';
import { MAX_FILES_PER_POST, MAX_FILE_SIZE_MB, MAX_CONTENT_CHARS, validateNewFiles, cardStyle } from '../timelineUtils';
import TimelineAvatar from './TimelineAvatar';

// "What's happening" box. The class the post goes to is shown at the top of the box (it is picked above,
// on the page) so nobody posts to the wrong class by accident.
const TimelineComposer = ({ authorName, courseName, disabled, posting, onPost }) => {
  const [content, setContent] = useState('');
  const [files, setFiles] = useState([]);
  const [fileError, setFileError] = useState('');
  const fileInputRef = useRef(null);

  // Previews are object URLs, released when a file is removed or the box unmounts.
  const previews = useMemo(() => files.map(file => ({ file, url: URL.createObjectURL(file) })), [files]);
  useEffect(
    () => () => {
      previews.forEach(preview => URL.revokeObjectURL(preview.url));
    },
    [previews]
  );

  const addFiles = event => {
    const added = Array.from(event.target.files || []);
    event.target.value = '';
    if (!added.length) return;
    const error = validateNewFiles(files, added);
    setFileError(error);
    if (!error) setFiles(prev => [...prev, ...added]);
  };

  const removeFile = index => {
    setFileError('');
    setFiles(prev => prev.filter((file, i) => i !== index));
  };

  const canPost = !disabled && !posting && (content.trim() || files.length);

  const submit = async () => {
    const posted = await onPost({ content: content.trim(), files });
    if (posted) {
      setContent('');
      setFiles([]);
      setFileError('');
    }
  };

  return (
    <div style={{ ...cardStyle, padding: 16, marginBottom: 16 }}>
      <div style={{ fontSize: 13, marginBottom: 10, color: colors.grey2, display: 'flex', alignItems: 'center' }}>
        <TimelineAvatar name={authorName} size={32} />
        <span style={{ marginLeft: 10 }}>
          Posting to {courseStatic.toLowerCase()}:{' '}
          {courseName ? (
            <span
              style={{
                background: '#EDE1F7',
                color: colors.accentDark,
                fontWeight: 'bold',
                borderRadius: 12,
                padding: '2px 10px',
              }}>
              {courseName}
            </span>
          ) : (
            <span style={{ color: '#e65100' }}>select a {courseStatic.toLowerCase()} above</span>
          )}
        </span>
      </div>
      <textarea
        className="form-control"
        rows={3}
        // The app's global `textarea.form-control` rule (paper-dashboard.css) zeroes the left/bottom padding.
        style={{
          padding: '10px 12px',
          maxHeight: 160,
          background: '#FBF8FD',
          borderColor: '#EDE1F7',
          borderRadius: 10,
        }}
        maxLength={MAX_CONTENT_CHARS}
        disabled={disabled || posting}
        placeholder="Share an update, photo or video with the class..."
        value={content}
        onChange={e => setContent(e.target.value)}
      />
      {!!previews.length && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 10 }}>
          {previews.map((preview, index) => (
            <div key={preview.url} style={{ position: 'relative', width: 96, height: 96 }}>
              {preview.file.type.startsWith('video/') ? (
                <video src={preview.url} muted style={{ width: 96, height: 96, objectFit: 'cover', borderRadius: 6 }} />
              ) : (
                <img
                  src={preview.url}
                  alt={preview.file.name}
                  style={{ width: 96, height: 96, objectFit: 'cover', borderRadius: 6 }}
                />
              )}
              <button
                type="button"
                aria-label={`Remove ${preview.file.name}`}
                disabled={posting}
                onClick={() => removeFile(index)}
                style={{
                  position: 'absolute',
                  top: 2,
                  right: 2,
                  width: 20,
                  height: 20,
                  lineHeight: '18px',
                  padding: 0,
                  border: 'none',
                  borderRadius: '50%',
                  background: 'rgba(0,0,0,0.65)',
                  color: colors.white,
                  cursor: 'pointer',
                }}>
                &times;
              </button>
            </div>
          ))}
        </div>
      )}
      {!!fileError && <div style={{ color: '#c62828', fontSize: 12, marginTop: 6 }}>{fileError}</div>}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 12 }}>
        <div>
          <input ref={fileInputRef} type="file" accept="image/*,video/*" multiple hidden onChange={addFiles} />
          <CustomButton
            size="small"
            variant="outlined"
            name="Add photos / videos"
            disabled={disabled || posting || files.length >= MAX_FILES_PER_POST}
            onClick={() => fileInputRef.current.click()}
          />
          <span style={{ fontSize: 12, color: '#9a9a9a', marginLeft: 8 }}>
            Up to {MAX_FILES_PER_POST} files, {MAX_FILE_SIZE_MB} MB each
          </span>
        </div>
        <CustomButton
          name="Post"
          disabled={!canPost}
          loading={posting}
          onClick={submit}
          style={canPost ? { backgroundColor: colors.accent, color: colors.white } : undefined}
        />
      </div>
    </div>
  );
};

export default TimelineComposer;
