import React from 'react';
import colors from 'config/colors';
import { initials } from '../timelineUtils';

const TimelineAvatar = ({ name, size = 40, admin = false }) => (
  <div
    style={{
      width: size,
      height: size,
      borderRadius: '50%',
      flexShrink: 0,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontWeight: 'bold',
      fontSize: size * 0.38,
      color: colors.white,
      background: admin
        ? `linear-gradient(135deg, ${colors.accentDark}, #3b0a5c)`
        : `linear-gradient(135deg, ${colors.accent}, #B05BD1)`,
    }}>
    {initials(name)}
  </div>
);

export default TimelineAvatar;
