import constants from 'config/constants';
import { formResMessage } from 'utils/commonFunc';

// Mirror the backend's timeline.upload.* settings (application.properties); the backend enforces them too.
export const MAX_FILES_PER_POST = 5;
export const MAX_FILE_SIZE_MB = 10;
export const MAX_CONTENT_CHARS = 3000;

// Who is calling, in the backend's terms. Only admins and teachers use the web dashboard's Timeline.
export const timelineUserFor = (role, userId) => {
  if (role === constants.roles.admin) return { userType: 'ADMIN', userId };
  if (role === constants.roles.teacher) return { userType: 'EMPLOYEE', userId };
  return null;
};

// -> error text, or '' when the files can go in a post (current files + the ones being added).
export const validateNewFiles = (current, added) => {
  if (current.length + added.length > MAX_FILES_PER_POST) return `You can attach at most ${MAX_FILES_PER_POST} files`;
  const wrongType = added.find(file => !/^(image|video)\//.test(file.type));
  if (wrongType) return `${wrongType.name} is not an image or video`;
  const tooBig = added.find(file => file.size > MAX_FILE_SIZE_MB * 1024 * 1024);
  if (tooBig) return `${tooBig.name} is larger than ${MAX_FILE_SIZE_MB} MB`;
  return '';
};

export const initials = name =>
  `${name || ''}`
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map(part => part.charAt(0).toUpperCase())
    .join('') || '?';

// Soft purple card look shared by the composer, posts and comments panel (same family as colors.accent).
export const cardStyle = {
  background: '#fff',
  borderRadius: 12,
  border: '1px solid #EDE1F7',
  boxShadow: '0 2px 10px rgba(91, 21, 132, 0.07)',
};

// The timeline backend answers with Spring's standard error body ({ detail, title, status }), which the shared
// formResMessage doesn't read (it looks for details / message) and so shows only "Something went wrong". Prefer the
// backend's own reason, e.g. "You do not have access to this course timeline".
export const timelineErrorMessage = err => {
  const detail = err?.response?.data?.detail;
  // Spring's "No static resource ..." means the server has no such URL, i.e. it runs a build without the timeline API.
  if (typeof detail === 'string' && detail.startsWith('No static resource')) {
    return 'Timeline is not available on the server yet. Please try again later.';
  }
  return typeof detail === 'string' && detail ? detail : formResMessage(err);
};
