import axios from 'axios';
import constants from '../../config/constants';

// Plain (non-thunk) axios calls - the Timeline page (views/admin/Timeline) keeps its own local state.
// Every timeline endpoint names the caller as ?userType=&userId= (ADMIN = school admin id, EMPLOYEE =
// teacher id) instead of reading it from the login token, so each call carries that pair.
const BASE = `${constants.API_BASE_URL}/api/timeline`;

const userParams = user => ({ userType: user.userType, userId: user.userId });

export const fetchTimelineFeedApi = ({ courseId, user, page = 0, size = 10, token }) =>
  axios.get(
    `${BASE}/courses/${courseId}/posts${constants.makeParams({ ...userParams(user), page, size })}`,
    constants.setHeader(token)
  );

// Multipart: text + up to a handful of image/video files (limits in timelineUtils, mirroring the backend's).
export const createTimelinePostApi = ({ courseId, user, content, files, token }) => {
  const formData = new FormData();
  formData.append('userType', user.userType);
  formData.append('userId', user.userId);
  if (content) formData.append('content', content);
  files.forEach(file => formData.append('files', file));
  return axios.post(`${BASE}/courses/${courseId}/posts`, formData, constants.setHeader(token, undefined, true));
};

export const deleteTimelinePostApi = ({ postId, user, token }) =>
  axios.delete(`${BASE}/posts/${postId}${constants.makeParams(userParams(user))}`, constants.setHeader(token));

export const fetchTimelineCommentsApi = ({ postId, user, token }) =>
  axios.get(`${BASE}/posts/${postId}/comments${constants.makeParams(userParams(user))}`, constants.setHeader(token));

// Media sits behind the login token, so an <img>/<video> can't point at the URL directly: it is fetched
// as a blob and shown from an object URL.
export const fetchTimelineMediaBlobApi = ({ mediaId, user, token }) =>
  axios.get(`${BASE}/media/${mediaId}${constants.makeParams(userParams(user))}`, {
    ...constants.setHeader(token),
    responseType: 'blob',
  });

export const addTimelineCommentApi = ({ postId, user, commentText, token }) =>
  axios.post(
    `${BASE}/posts/${postId}/comments${constants.makeParams(userParams(user))}`,
    { commentText },
    constants.setHeader(token)
  );
